∀ (oracle : ℕ → Bool) (x : ℕ),
  UEOT.V3.Compression.TheoryCompletion.UnifiedClosure.C3ExecutableSearch.scan oracle x 0 =
    { found := none, queries := [] }

∀ (oracle : ℕ → Bool) (x fuel : ℕ),
  UEOT.V3.Compression.TheoryCompletion.UnifiedClosure.C3ExecutableSearch.scan oracle x fuel.succ =
    if oracle x = true then { found := some x, queries := [x] }
    else
      have rest := UEOT.V3.Compression.TheoryCompletion.UnifiedClosure.C3ExecutableSearch.scan oracle (x + 1) fuel;
      { found := rest.found, queries := x :: rest.queries }

∀ (oracle : ℕ → Bool) (x x_1 : ℕ),
  UEOT.V3.Compression.TheoryCompletion.UnifiedClosure.C3ExecutableSearch.scan oracle x x_1 =
    match x, x_1 with
    | x, 0 => { found := none, queries := [] }
    | start, fuel.succ =>
      if oracle start = true then { found := some start, queries := [start] }
      else
        have rest :=
          UEOT.V3.Compression.TheoryCompletion.UnifiedClosure.C3ExecutableSearch.scan oracle (start + 1) fuel;
        { found := rest.found, queries := start :: rest.queries }
